package com.nivor.ai;
import com.nivor.ai.AiDtos.PreferenceRequest;import com.nivor.ai.AiDtos.PreferenceView;
import com.nivor.goal.*;import com.nivor.planner.*;import com.nivor.task.*;import com.nivor.user.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)public class AiContextService{private final AiAccessRepository prefs;private final AiConversationRepository unused;private final UserService users;private final TaskRepository tasks;private final CalendarEventRepository events;private final GoalRepository goals;public AiContextService(AiAccessRepository p,UserService u,TaskRepository t,CalendarEventRepository e,GoalRepository g){prefs=p;users=u;tasks=t;events=e;goals=g;unused=null;}
 public boolean enabled(String email,AiContextCategory c){Long id=users.getByEmail(email).getId();return prefs.findByUser_IdAndCategory(id,c).map(AiAccessPreference::isEnabled).orElse(!Set.of(AiContextCategory.FINANCE,AiContextCategory.HEALTH,AiContextCategory.JOURNAL).contains(c));}
 public String forRequest(String email,String request){String q=request.toLowerCase(Locale.ROOT);boolean today=q.contains("today")||q.contains("day")||q.contains("schedule")||q.contains("focus");if(!today)return "";long id=users.getByEmail(email).getId();StringBuilder c=new StringBuilder();LocalDate d=LocalDate.now();if(enabled(email,AiContextCategory.TASKS)){c.append("Today's tasks: ");tasks.findAllByUser_IdOrderByDueDateAscDueTimeAsc(id).stream().filter(t->t.getStatus()!=TaskStatus.COMPLETED&&(d.equals(t.getDueDate())||t.getDueDate()==null)).limit(20).forEach(t->c.append(t.getTitle()).append(t.getDueTime()==null?"":" at "+t.getDueTime()).append("; "));}if(enabled(email,AiContextCategory.CALENDAR)){c.append(" Today's events: ");events.findAllByUser_IdAndStartTimeLessThanEqualAndEndTimeGreaterThanEqualOrderByStartTimeAsc(id,d.plusDays(1).atStartOfDay(),d.atStartOfDay()).stream().limit(20).forEach(e->c.append(e.getTitle()).append(" at ").append(e.getStartTime()).append("; "));}if(enabled(email,AiContextCategory.GOALS)){c.append(" Active goals: ");goals.findAllByUser_IdOrderByDeadlineAsc(id).stream().filter(g->g.getStatus()==GoalStatus.ACTIVE).limit(10).forEach(g->c.append(g.getTitle()).append(" ("+g.getProgress()+"%); "));}return c.toString().substring(0,Math.min(c.length(),8000));}
 public List<PreferenceView> preferences(String email){long id=users.getByEmail(email).getId();Map<AiContextCategory,Boolean> saved=new EnumMap<>(AiContextCategory.class);prefs.findAllByUser_Id(id).forEach(p->saved.put(p.getCategory(),p.isEnabled()));return Arrays.stream(AiContextCategory.values()).map(c->new PreferenceView(c,saved.getOrDefault(c,!Set.of(AiContextCategory.FINANCE,AiContextCategory.HEALTH,AiContextCategory.JOURNAL).contains(c)))).toList();}
 @Transactional public PreferenceView update(String email,PreferenceRequest r){var user=users.getByEmail(email);AiAccessPreference p=prefs.findByUser_IdAndCategory(user.getId(),r.category()).orElseGet(AiAccessPreference::new);p.setUser(user);p.setCategory(r.category());p.setEnabled(r.enabled());prefs.save(p);return new PreferenceView(p.getCategory(),p.isEnabled());}}
